package edu.uiu.aoop.careerforge.controller;

import edu.uiu.aoop.careerforge.dto.ApiResponse;
import edu.uiu.aoop.careerforge.exception.ApiException;
import edu.uiu.aoop.careerforge.security.AppPrincipal; import edu.uiu.aoop.careerforge.service.CommunityService; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/community") public class CommunityController {private final CommunityService service;public CommunityController(CommunityService service){this.service=service;} @GetMapping("/posting-status") Map<String,Object> status(@AuthenticationPrincipal AppPrincipal p){return service.postingStatus(p.id(),p.role());} @GetMapping("/posts") List<Map<String,Object>> posts(@AuthenticationPrincipal AppPrincipal p){return service.posts(p.id(),p.role());} @PostMapping("/posts") Map<String,Object> create(@AuthenticationPrincipal AppPrincipal p,@RequestBody Map<String,Object>b){return service.create(p.id(),p.role(),p.name(),b);}@DeleteMapping("/posts/{id}") Map<String,Object> delete(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id){return service.deletePost(p.id(),p.role(),id);}@PostMapping("/posts/{id}/like") Map<String,Object> like(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id){return service.like(p.id(),id);}@GetMapping("/posts/{id}/comments") List<Map<String,Object>> comments(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id){return service.comments(p.id(),id);}@PostMapping("/posts/{id}/comments") Map<String,Object> comment(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id,@RequestBody Map<String,Object>b){return service.comment(p.id(),p.role(),p.name(),id,String.valueOf(b.getOrDefault("content","")));}@DeleteMapping("/comments/{id}") Map<String,Object> deleteComment(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id){return service.deleteComment(p.id(),p.role(),id);}@PostMapping("/posts/{id}/share") Map<String,Object> share(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id){return service.share(p.id(),id);}@PostMapping("/posts/{id}/report") Map<String,Object> report(@AuthenticationPrincipal AppPrincipal p,@PathVariable Long id,@RequestBody Map<String,Object>b){return service.report(p.id(),id,b);}}
